def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_bids = []
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        alive_opponents.append(opp)
        if opp.get('budget', 0) <= DAILY_SALARY * 0.6 or opp.get('hp', 0) <= 2:
            weak_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) >= bid * 0.8:
                dangerous_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.25))

    strongest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_danger = max(dangerous_bids) if dangerous_bids else strongest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if supply <= 17:
        urgency += 2
    elif supply <= 20:
        urgency += 1

    if day >= 8:
        urgency += 1

    affordable_cap = min(budget, DAILY_SALARY * 1.35)

    if urgency >= 6:
        target = max(DAILY_SALARY * 0.95, strongest_danger + 2.0)
    elif urgency >= 4:
        target = max(DAILY_SALARY * 0.72, strongest_danger + 1.25)
    elif urgency >= 2:
        target = max(DAILY_SALARY * (0.48 + 0.18 * scarcity), strongest_danger * 0.72)
    else:
        target = DAILY_SALARY * (0.22 + 0.18 * scarcity)

    if weak_count >= len(alive_opponents) - 1 and urgency <= 2:
        target *= 0.72

    if strongest_prev >= DAILY_SALARY * 1.5 and urgency <= 3:
        target = min(target, DAILY_SALARY * 0.38)

    if budget < DAILY_SALARY * 0.8:
        target = min(target, budget * 0.92)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.9)

    bid = min(affordable_cap, target)
    if bid < 0:
        bid = 0.0
    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.6 # Default bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 5:
                bid = DAILY_SALARY * 0.5
            else:
                bid = DAILY_SALARY * 0.95
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            if my_status['hp'] > 3:
                bid = max(DAILY_SALARY * 0.65, highest_prev_bid + 2.0)
            else:
                bid = DAILY_SALARY * 0.85
        else:
            if my_status['hp'] > 7:
                bid = DAILY_SALARY * 0.4
            elif my_status['hp'] > 3:
                bid = DAILY_SALARY * 0.55
            else:
                bid = DAILY_SALARY * 0.75
    else:
        if my_status['hp'] <= 3:
            bid = DAILY_SALARY * 0.9
        elif my_status['hp'] <= 7:
            bid = DAILY_SALARY * 0.7
        else:
            bid = DAILY_SALARY * 0.5

    if current_supply <= 17.0:
        bid *= 1.1
    elif current_supply >= 23.0:
        bid *= 0.9

    bid = max(1.0, bid)
    bid = min(bid, my_status['budget'])

    return bid
